{"code":"import pandas as pd
import numpy as np

raw = pd.read_csv('raw_responses.csv')
out = pd.read_csv('pipeline_output.csv')

def half_round(val):
    # Halves always round up, so 4.5 becomes 5 and 10.5 becomes 11.
    # In python, round(4.5) is 4 (round to even). We want round half up.
    # Using Decimal or custom check:
    from decimal import Decimal, ROUND_HALF_UP
    return int(Decimal(str(val)).quantize(Decimal('1'), rounding=ROUND_HALF_UP))

def score_phq9(row):
    items = [f'phq9_{i}' for i in range(1, 10)]
    vals = []
    missing = 0
    for it in items:
        v = row[it]
        if pd.isna(v) or v == -9 or v < 0 or v > 3:
            missing += 1
        else:
            vals.append(v)

    if missing >= 2:
        return np.nan, np.nan, np.nan, np.nan
    elif missing == 1:
        s = sum(vals)
        prorated_total = half_round(s * 9 / 8)
        prorated_flag = True
    else:
        prorated_total = sum(vals)
        prorated_flag = False

    tot = prorated_total

    # band
    if tot <= 4:
        band = 'none-minimal'
    elif tot <= 9:
        band = 'mild'
    elif tot <= 14:
        band = 'moderate'
    elif tot <= 19:
        band = 'moderately severe'
    else:
        band = 'severe'

    # self harm flag (q9)
    q9 = row['phq9_9']
    if pd.isna(q9) or q9 == -9 or q9 < 0 or q9 > 3:
        sh_flag = np.nan
    else:
        sh_flag = (q9 in [1, 2, 3])

    return tot, band, prorated_flag, sh_flag

def score_gad7(row):
    items = [f'gad7_{i}' for i in range(1, 8)]
    vals = []
    missing = 0
    for it in items:
        v = row[it]
        if pd.isna(v) or v == -9 or v < 0 or v > 3:
            missing += 1
        else:
            vals.append(v)

    if missing >= 2:
        return np.nan, np.nan, np.nan
    elif missing == 1:
        s = sum(vals)
        prorated_total = half_round(s * 7 / 6)
        prorated_flag = True
    else:
        prorated_total = sum(vals)
        prorated_flag = False

    tot = prorated_total

    if tot <= 4:
        band = 'minimal'
    elif tot <= 9:
        band = 'mild'
    elif tot <= 14:
        band = 'moderate'
    else:
        band = 'severe'

    return tot, band, prorated_flag

def score_rses(row):
    neg_items = {3, 5, 8, 9, 10}
    vals = []
    missing = 0
    for i in range(1, 11):
        it = f'rses_{i}'
        v = row[it]
        if pd.isna(v) or v == -9 or v < 0 or v > 3:
            missing += 1
        else:
            if i in neg_items:
                vals.append(3 - v)
            else:
                vals.append(v)

    if missing >= 2:
        return np.nan, np.nan
    elif missing == 1:
        s = sum(vals)
        prorated_total = half_round(s * 10 / 9)
        prorated_flag = True
    else:
        prorated_total = sum(vals)
        prorated_flag = False

    tot = prorated_total
    return tot, prorated_flag

results = []
for idx, row in raw.iterrows():
    p_tot, p_band, p_pro, p_sh = score_phq9(row)
    g_tot, g_band, g_pro = score_gad7(row)
    r_tot, r_pro = score_rses(row)
    results.append({
        'respondent_id': row['respondent_id'],
        'phq9_total': p_tot,
        'phq9_band': p_band,
        'phq9_prorated': p_pro,
        'phq9_self_harm_flag': p_sh,
        'gad7_total': g_tot,
        'gad7_band': g_band,
        'gad7_prorated': g_pro,
        'rses_total': r_tot,
        'rses_prorated': r_pro
    })

my_out = pd.DataFrame(results)

# Compare with pipeline output
for col in out.columns:
    if col == 'respondent_id':
        continue
    # compare values
    # handle booleans and floats/nans
    mismatches = 0
    for i in range(len(raw)):
        val_pipeline = out.loc[i, col]
        val_mine = my_out.loc[i, col]

        # Check nan equivalence
        is_nan_p = pd.isna(val_pipeline)
        is_nan_m = pd.isna(val_mine)
        if is_nan_p and is_nan_m:
            continue
        if is_nan_p != is_nan_m:
            mismatches += 1
            if mismatches <= 3:
                print(f"Col {col} row {i} ({raw.loc[i, 'respondent_id']}): pipeline={val_pipeline}, mine={val_mine} (NaN mismatch)")
            continue

        # check equality
        if val_pipeline != val_mine:
            mismatches += 1
            if mismatches <= 3:
                print(f"Col {col} row {i} ({raw.loc[i, 'respondent_id']}): pipeline={val_pipeline}, mine={val_mine}")

    print(f"Column {col}: {mismatches} mismatches")
"}

